import { expect, test, type Page } from "@playwright/test";
import path from "node:path";
import { expectNoHorizontalScroll, login } from "./helpers";

// Fictional Geography data (tests/e2e/fixtures, generated by the API test fixtures). Needs API with seed.
const F = (n: string) => path.join(import.meta.dirname, "fixtures", n);
const shot = (name: string, project: string) => `test-results/upload/${name}-${project}.png`;

async function openForm(page: Page) {
  await login(page, "gv.dia@preclass.local");
  await page.goto("/sources");
  await page.getByRole("button", { name: "Thêm nguồn" }).click();
  await page.getByText("Tải tệp (Word, PDF, Excel, PowerPoint)").click();
  await expect(page.getByText("Kéo tệp vào đây hoặc bấm để chọn")).toBeVisible();
}

async function save(page: Page, file: string, title: string) {
  await page.getByLabel("Tên nguồn").fill(title);
  await page.locator(".dropzone input").setInputFiles(F(file));
  await page.getByRole("button", { name: "Lưu nguồn" }).click();
}

test("teacher uploads XLSX, PPTX, PDF and sees anchors by sheet / slide / page", async ({ page }, info) => {
  const tag = `${info.project.name}-${Date.now()}`; // titles must be unique per run
  await openForm(page);
  await page.screenshot({ path: shot("dropzone", info.project.name), fullPage: true });
  await expectNoHorizontalScroll(page);

  await save(page, "so-lieu-minh-hoa.xlsx", `Bảng số liệu ${tag}`);
  await expect(page.getByText(/Đã đọc \d+ đoạn nguồn/)).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText("Sheet Dan so", { exact: false }).first()).toBeVisible();
  await expect(page.locator(".anchor-preview")).toContainText("Sheet Dan so, ô B2");
  await page.screenshot({ path: shot("result-xlsx", info.project.name), fullPage: true });
  await page.getByRole("button", { name: "Xong" }).click();

  await page.getByRole("button", { name: "Thêm nguồn" }).click();
  await page.getByText("Tải tệp (Word, PDF, Excel, PowerPoint)").click();
  await save(page, "bai-minh-hoa.pptx", `Bài trình chiếu ${tag}`);
  await expect(page.locator(".anchor-preview")).toContainText("Slide 1", { timeout: 30_000 });
  await page.getByRole("button", { name: "Xong" }).click();

  await page.getByRole("button", { name: "Thêm nguồn" }).click();
  await page.getByText("Tải tệp (Word, PDF, Excel, PowerPoint)").click();
  await save(page, "bai-minh-hoa.pdf", `Bài PDF ${tag}`);
  await expect(page.locator(".anchor-preview")).toContainText("Trang 1, đoạn 1", { timeout: 30_000 });
  await page.getByRole("button", { name: "Xong" }).click();

  // Source Inspector (source page) shows the friendly locator too.
  await page.getByRole("link", { name: `Bài PDF ${tag}` }).click();
  await expect(page.locator("table")).toContainText("Trang 1, đoạn 1");
  await page.screenshot({ path: shot("source-page-pdf", info.project.name), fullPage: true });
});

test("scanned PDF and hostile files give friendly messages", async ({ page }, info) => {
  const tag = `${info.project.name}-${Date.now()}`;
  await openForm(page);
  await save(page, "anh-scan.pdf", `Scan ${tag}`);
  await expect(page.getByText("File là ảnh scan, vui lòng nạp bản có chữ (Word/PDF xuất từ Word).")).toBeVisible({ timeout: 30_000 });
  await page.screenshot({ path: shot("scanned", info.project.name), fullPage: true });
  await page.getByRole("button", { name: "Xong" }).click();

  for (const [file, msg] of [["co-macro.xlsx", /macro/], ["pdf-co-js.pdf", /mã tự chạy/], ["gia-duoi.pdf", /Chỉ nhận tệp/]] as const) {
    await page.getByRole("button", { name: "Thêm nguồn" }).click();
    await page.getByText("Tải tệp (Word, PDF, Excel, PowerPoint)").click();
    await save(page, file, `Độc ${file}`);
    await expect(page.getByRole("alert").filter({ hasText: msg })).toBeVisible({ timeout: 30_000 });
    await page.getByRole("button", { name: "Đóng", exact: true }).click();
  }
});
